import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

@DisplayName("10/2_remove_element")
class SolutionTest {

    private void assertContents(
        int[] nums,
        int length,
        int... expectedValues
    ) {

        Map<Integer, Integer> expected = new HashMap<>();

        for (int value : expectedValues) {
            expected.merge(value, 1, Integer::sum);
        }

        Map<Integer, Integer> actual = new HashMap<>();

        for (int i = 0; i < length; i++) {
            actual.merge(nums[i], 1, Integer::sum);
        }

        assertEquals(expected, actual);
    }

    @Test
    void officialExampleOne() {

        Completed solution = new Completed();

        int[] nums = {3, 2, 2, 3};

        int k = solution.removeElement(nums, 3);

        assertEquals(2, k);
        assertContents(nums, k, 2, 2);
    }

    @Test
    void officialExampleTwo() {

        Completed solution = new Completed();

        int[] nums = {0, 1, 2, 2, 3, 0, 4, 2};

        int k = solution.removeElement(nums, 2);

        assertEquals(5, k);
        assertContents(nums, k, 0, 0, 1, 3, 4);
    }

    @Test
    void emptyArray() {

        Completed solution = new Completed();

        int[] nums = {};

        int k = solution.removeElement(nums, 1);

        assertEquals(0, k);
    }

    @Test
    void removeNothing() {

        Completed solution = new Completed();

        int[] nums = {1, 2, 3};

        int k = solution.removeElement(nums, 4);

        assertEquals(3, k);
        assertContents(nums, k, 1, 2, 3);
    }

    @Test
    void removeEverything() {

        Completed solution = new Completed();

        int[] nums = {7, 7, 7, 7};

        int k = solution.removeElement(nums, 7);

        assertEquals(0, k);
    }

    @Test
    void singleElementKept() {

        Completed solution = new Completed();

        int[] nums = {5};

        int k = solution.removeElement(nums, 1);

        assertEquals(1, k);
        assertContents(nums, k, 5);
    }

    @Test
    void singleElementRemoved() {

        Completed solution = new Completed();

        int[] nums = {5};

        int k = solution.removeElement(nums, 5);

        assertEquals(0, k);
    }
}
